from pathlib import Path
root=Path('public/shared')
def kitchen(front='#515e59',wood='#ab875e',island=False):
 defs='<defs><linearGradient id="wall" x2="1" y2="1"><stop stop-color="#ede9df"/><stop offset="1" stop-color="#d5d0c2"/></linearGradient><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#c9c0ab"/><stop offset="1" stop-color="#e7e0d0"/></linearGradient><linearGradient id="wood"><stop stop-color="'+wood+'"/><stop offset=".5" stop-color="#c4a27a"/><stop offset="1" stop-color="'+wood+'"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="7"/></filter></defs>'
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 420">{defs}<rect width="700" height="420" fill="url(#wall)"/><path d="M0 318H700V420H0Z" fill="url(#floor)"/><path d="M0 0 135 60v260L0 375Z" fill="#d9d4c7"/><path d="M135 318 700 320M0 375l700-25" stroke="#b8b19d" opacity=".4"/><ellipse cx="395" cy="337" rx="280" ry="20" fill="#4c4938" opacity=".15" filter="url(#shadow)"/>'
 s+='<rect x="150" y="202" width="500" height="26" fill="#c3b293"/><rect x="145" y="224" width="510" height="7" fill="#d1c5ad"/>'
 for i in range(7):
  x=151+i*71;s+=f'<rect x="{x}" y="233" width="69" height="89" fill="{front}"/><path d="M{x+1} 234v87" stroke="#fff" opacity=".12"/><path d="M{x+5} 240h59" stroke="#1f2b24" opacity=".4" stroke-width="3"/>'
  if i in [2,3]:s+=f'<path d="M{x+1} 263h67M{x+1} 293h67" stroke="#1d2723" opacity=".4"/>'
 s+='<rect x="150" y="322" width="500" height="12" fill="#303a31"/><rect x="150" y="80" width="80" height="143" fill="url(#wood)"/><rect x="151" y="80" width="78" height="53" fill="#232d2a"/><rect x="160" y="95" width="60" height="29" fill="#151d1c"/><path d="M159 91h62" stroke="#9b9b8a" stroke-width="3"/>'
 for i in range(5):
  x=245+i*80;s+=f'<rect x="{x}" y="80" width="78" height="89" fill="{front}"/><path d="M{x+39} 81v87" stroke="#15241d" opacity=".5"/>'
 s+='<rect x="245" y="170" width="399" height="3" fill="#fbecc1"/><rect x="500" y="217" width="70" height="6" rx="3" fill="#5e685f"/><path d="M536 217v-19q0-15 12-15h9" fill="none" stroke="#6a736e" stroke-width="4"/><ellipse cx="319" cy="224" rx="23" ry="5" fill="#a28a62"/><path d="M304 194q15-16 30 0l-4 28h-21Z" fill="#b4a78b"/><path d="M319 193v-31M319 178q-19-19-17-30M319 178q24-14 24-33" fill="none" stroke="#687b5e" stroke-width="3"/><ellipse cx="303" cy="153" rx="8" ry="15" fill="#7a8b64" transform="rotate(-25 303 153)"/><ellipse cx="338" cy="150" rx="8" ry="16" fill="#76885f" transform="rotate(27 338 150)"/>'
 if island:s+='<ellipse cx="420" cy="383" rx="185" ry="15" fill="#504630" opacity=".12" filter="url(#shadow)"/><path d="M265 293h330v86H265Z" fill="'+front+'"/><path d="M596 293l40-21v86l-40 21Z" fill="#536b5a"/><path d="M254 291 294 268h350l-43 25Z" fill="#e4d9c1"/><path d="M254 291h347v7H254Z" fill="#c4b799"/><path d="M376 298v79M486 298v79" stroke="#16271b" opacity=".35"/>'
 return s+'</svg>'
root.joinpath('kitchen.svg').write_text(kitchen('#c6bcaa'))
root.joinpath('example-1.svg').write_text(kitchen('#374746'))
root.joinpath('example-2.svg').write_text(kitchen('#f3f0e5'))
root.joinpath('example-3.svg').write_text(kitchen('#859780',island=True))
wardrobe='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 420"><defs><linearGradient id="w"><stop stop-color="#ede8dc"/><stop offset="1" stop-color="#d7cfbe"/></linearGradient></defs><rect width="700" height="420" fill="url(#w)"/><rect y="360" width="700" height="60" fill="#c8bfa8"/><path d="M40 40h615v315H40Z" fill="#a0805d"/>'
for i in range(5):
 x=45+i*122;wardrobe+=f'<rect x="{x}" y="45" width="118" height="305" fill="'+('#b59a76' if i==2 else '#d0c4ae')+'"/>'
 if i!=2:wardrobe+=f'<path d="M{x+59} 45v305" stroke="#ada28d"/><path d="M{x+49} 180v48M{x+68} 180v48" stroke="#918367" stroke-width="3"/>'
 else:
  wardrobe+=f'<path d="M{x} 115h118M{x} 240h118M{x} 290h118" stroke="#8a7154" stroke-width="4"/><path d="M{x+5} 148h108" stroke="#555f57" stroke-width="3"/>'
  for j,c in enumerate(['#eee4d1','#687f74','#a8a494']):wardrobe+=f'<path d="M{x+20+j*28} 155h20v65h-20Z" fill="{c}"/>'
wardrobe+='<rect x="40" y="350" width="615" height="10" fill="#a18b6c"/><ellipse cx="351" cy="386" rx="230" ry="12" fill="#b5aa94" opacity=".4"/></svg>'
root.joinpath('wardrobe.svg').write_text(wardrobe)
